#include <cstdint>
#include <stdexcept>
#include <utility>

typedef struct counter counter;
struct counter { int32_t value{ 0 }; };
static int g_live = 0;
extern "C" int32_t counter_create(counter** out) { if (!out) return 1; *out = new counter{}; ++g_live; return 0; }
extern "C" void counter_destroy(counter* c) { if (c) { delete c; --g_live; } }
extern "C" int32_t counter_add(counter* c, int32_t n) { if (!c) return 1; c->value += n; return 0; }
extern "C" int32_t counter_value(const counter* c, int32_t* out) { if (!c || !out) return 1; *out = c->value; return 0; }
int liveCounters() { return g_live; }

class Counter
{
public:
    Counter() { check(counter_create(&m_handle)); }
    ~Counter() { counter_destroy(m_handle); }

    Counter(const Counter&) = delete;
    Counter& operator=(const Counter&) = delete;

    Counter(Counter&& other) noexcept : m_handle{ std::exchange(other.m_handle, nullptr) } {}
    Counter& operator=(Counter&& other) noexcept
    {
        if (this != &other)
        {
            counter_destroy(m_handle);
            m_handle = std::exchange(other.m_handle, nullptr);
        }
        return *this;
    }

    void add(int32_t n) { check(counter_add(m_handle, n)); }
    int32_t value() const { int32_t v{ 0 }; check(counter_value(m_handle, &v)); return v; }
    counter* get() const noexcept { return m_handle; }

private:
    static void check(int32_t result) { if (result != 0) throw std::runtime_error("counter call failed"); }
    counter* m_handle{ nullptr };
};

unitTests:
TEST("create and destroy") { const int before = liveCounters(); { Counter c; c.add(3); c.add(4); CHECK_EQ(c.value(), 7); CHECK_EQ(liveCounters(), before + 1); } CHECK_EQ(liveCounters(), before); }
TEST("move construct") { const int before = liveCounters(); { Counter a; a.add(2); Counter b{ std::move(a) }; CHECK(a.get() == nullptr); CHECK_EQ(b.value(), 2); CHECK_EQ(liveCounters(), before + 1); } CHECK_EQ(liveCounters(), before); }
TEST("move assign destroys the old handle") { const int before = liveCounters(); { Counter a; Counter b; CHECK_EQ(liveCounters(), before + 2); b = std::move(a); CHECK_EQ(liveCounters(), before + 1); } CHECK_EQ(liveCounters(), before); }
TEST("self move assignment") { const int before = liveCounters(); { Counter a; a.add(5); Counter& same = a; a = std::move(same); CHECK_EQ(a.value(), 5); } CHECK_EQ(liveCounters(), before); }
TEST("moved-from object throws") { Counter a; Counter b{ std::move(a) }; bool threw = false; try { a.add(1); } catch (const std::runtime_error&) { threw = true; } CHECK(threw); }
TEST("not copyable") { CHECK(!std::is_copy_constructible_v<Counter>); CHECK(!std::is_copy_assignable_v<Counter>); CHECK(std::is_nothrow_move_constructible_v<Counter>); }

